function radixConvert(value, fromBase, toBase){
  fromBase=fromBase||16; toBase=toBase||10;
  if(fromBase<2||fromBase>36||toBase<2||toBase>36) return {ok:false, reason:'base 2-36'};
  var s=String(value==null?'':value).trim().replace(/^0[xXoObB]/,'');
  var v;
  if(fromBase===10){ if(!/^[+-]?\d+$/.test(s)) return {ok:false, reason:'not decimal'}; v=parseInt(s,10); }
  else { if(!/^[0-9a-zA-Z]+$/.test(s)) return {ok:false, reason:'bad chars'}; v=parseInt(s,fromBase); }
  if(isNaN(v)) return {ok:false, reason:'invalid'};
  return {ok:true, value:v.toString(toBase).toUpperCase(), dec:v};
}

var EXPORTS={radixConvert:radixConvert};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.RadixForgePure = EXPORTS; }
